331	// A retry block is either absent (one attempt, no waiting) or present with all
332	// four parameters together, each within the same ranges the engine enforces
333	// for business action retries and compensation retries alike.
334	function compileRetry(config, label) {
335	  if (!isUsableObject(config)) {
336	    throw new Error(`${label}: retry must be an object`);
337	  }
338	  const missing = RETRY_FIELDS.filter(field => !Object.hasOwn(config, field) || config[field] === undefined);
339	  if (missing.length > 0) {
340	    throw new Error(`${label}: retry config must define all of ${RETRY_FIELDS.join(', ')} together (missing: ${missing.join(', ')})`);
341	  }
342	  if (!isIntegerIn(config.attempts, 1, 10)) {
343	    throw new Error(`${label}: retry.attempts must be an integer between 1 and 10`);
344	  }
345	  if (!isIntegerIn(config.initialDelayMs, 0, 60000)) {
346	    throw new Error(`${label}: retry.initialDelayMs must be an integer between 0 and 60000 milliseconds`);
347	  }
348	  if (!isIntegerIn(config.maxDelayMs, 0, 60000)) {
349	    throw new Error(`${label}: retry.maxDelayMs must be an integer between 0 and 60000 milliseconds`);
350	  }
351	  if (typeof config.backoffFactor !== 'number' || !Number.isFinite(config.backoffFactor)
352	    || config.backoffFactor < 1 || config.backoffFactor > 4) {
353	    throw new Error(`${label}: retry.backoffFactor must be a finite number between 1 and 4`);
354	  }
355	  if (config.maxDelayMs < config.initialDelayMs) {
356	    throw new Error(`${label}: retry.maxDelayMs must not be less than retry.initialDelayMs`);
357	  }
358	  return {
359	    attempts: config.attempts,
360	    initialDelayMs: config.initialDelayMs,
361	    backoffFactor: config.backoffFactor,
362	    maxDelayMs: config.maxDelayMs,
363	  };
