366	// An action node either keeps the legacy `message` behavior, names a business
367	// operation the caller supplies at run time, and/or declares a compensation
368	// operation that undoes its business effect. Both retry blocks are optional
369	// and, absent, mean exactly one attempt with no waiting.
370	function compileAction(node) {
371	  let name = null;
372	  if (Object.hasOwn(node, 'operation') && node.operation !== undefined) {
373	    if (typeof node.operation !== 'string' || node.operation.trim().length === 0) {
374	      throw new Error(`action node ${node.id}: operation must be a non-empty string name`);
375	    }
376	    name = node.operation;
377	  }
378	
379	  let retry = { ...DEFAULT_RETRY };
380	  if (Object.hasOwn(node, 'retry') && node.retry !== undefined) {
381	    if (!name) {
382	      throw new Error(`action node ${node.id}: retry config is only allowed on an action that names an operation`);
383	    }
384	    retry = compileRetry(node.retry, `action node ${node.id}`);
385	  }
386	
387	  let compensation = null;
388	  if (Object.hasOwn(node, 'compensation') && node.compensation !== undefined) {
389	    if (!isUsableObject(node.compensation)) {
390	      throw new Error(`action node ${node.id}: compensation must be an object`);
391	    }
392	    if (!name) {
393	      throw new Error(`action node ${node.id}: compensation is only allowed on an action that names an operation`);
394	    }
395	    const config = node.compensation;
396	    if (typeof config.operation !== 'string' || config.operation.trim().length === 0) {
397	      throw new Error(`action node ${node.id}: compensation.operation must be a non-empty string name`);
398	    }
399	    let compRetry = { ...DEFAULT_RETRY };
400	    if (Object.hasOwn(config, 'retry') && config.retry !== undefined) {
401	      compRetry = compileRetry(config.retry, `action node ${node.id} compensation`);
402	    }
403	    compensation = { name: config.operation, retry: compRetry };
404	  }
405	
406	  // A legacy message action (no operation) is validated through the single
407	  // configured-value gate (assertConfiguredCopy below) — the same rule, with
408	  // action-specific wording, that end-node results use — covering every
409	  // message action including ones on untaken branches and entry-unreachable
410	  // ones. An action that names an operation ignores its message entirely, so
411	  // an unused uncloneable or shared-memory message is never rejected for it.
412	  // The gate only proves the message was safe as it was then; the same rule
413	  // is re-enforced at the action's own execution moment by readConfiguredCopy.
414	  if (name === null) {
